cardCss:
.dc-act { width:60px;height:60px;border-radius:9999px;display:inline-flex;align-items:center;justify-content:center;background:var(--action-btn-bg,#eef2f7);color:var(--ink-3,#64748b);border:none;cursor:pointer;transition:all .18s ease;font-size:25px; }
.dc-act:hover { background:var(--primary,#0f766e);color:#fff;transform:translateY(-2px);box-shadow:0 4px 12px rgba(15,118,110,.25); }
.dc-act:active { transform:scale(.9); }
.dc-act.is-active { background:var(--primary,#0f766e);color:#fff; }
.dc-act.act-mark.is-active { background:var(--unknown,#f43f5e);color:#fff; }
.dc-act.act-fav.is-active { background:var(--amber,#d97706);color:#fff; }
.dc-scroll { scrollbar-width:thin;scrollbar-color:var(--line) transparent; }
.dc-scroll::-webkit-scrollbar { width:8px; }
.dc-scroll::-webkit-scrollbar-thumb { background:var(--line);border-radius:8px; }
body.dark-mode .dc-act { background:#1f2937;color:#cbd5e1; }
body.dark-mode .dc-act:hover,body.dark-mode .dc-act.is-active { color:#fff; }

.ew-word { color: var(--primary, #0f766e); }
.ew-phon { color: var(--ink-2, #475569); }
.ew-index { color: var(--ink-3, #64748b); }
.ew-def-en { background: var(--action-btn-bg, #f1f5f9); border-left: 3px solid var(--primary, #0f766e); padding-left: 14px; }
.dc-card.ew { border-left: 4px solid var(--primary, #0f766e); }
.dc-card.ew.highlighted { border-left-color: var(--unknown, #f43f5e); background: #fef6f3; }
body.dark-mode .ew-def-en { background: #1f2937; }
body.dark-mode .dc-card.ew.highlighted { background: #2a1417; }

/* ===== Flashcard flip (marked cards) ===== */
.dc-card.ew.flash { min-height: 340px; padding: 0; overflow: hidden; }
.ew-flash { perspective: 1400px; width: 100%; height: 100%; min-height: 340px; position: relative; display: flex; flex-direction: column; }
.ew-flash-inner { position: relative; width: 100%; flex: 1; min-height: 0; transform-style: preserve-3d; transition: transform .5s cubic-bezier(.4,.2,.2,1); }
.ew-flash.flipped .ew-flash-inner { transform: rotateY(180deg); }
.ew-face { position: absolute; inset: 0; backface-visibility: hidden; -webkit-backface-visibility: hidden; display: flex; flex-direction: column; overflow-y: auto; }
.ew-front { padding: 18px 16px; }
.ew-back { transform: rotateY(180deg); padding: 18px 16px; background: #fef6f3; }
body.dark-mode .ew-back { background: #2a1417; }
.ew-flash-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.ew-flash-badge { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 700; color: var(--unknown,#f43f5e); background: var(--unknown-soft,#ffe4e6); border: 1px solid rgba(244,63,94,.25); border-radius: 20px; padding: 3px 10px; }
.ew-flash-actions { display: flex; gap: 8px; }
.ew-flash-actions .dc-act { width: 48px; height: 48px; font-size: 20px; }
.ew-flash-body { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 10px; min-height: 0; cursor: pointer; }
.ew-flash-word { font-size: calc(34px*var(--card-font-scale,1)); font-weight: 800; color: var(--primary,#0f766e); letter-spacing: .5px; line-height: 1.3; word-break: break-word; }
.ew-flash-phon { font-size: calc(16px*var(--card-font-scale,1)); color: var(--ink-2,#475569); }
.ew-flash-hint { font-size: 12px; color: var(--ink-3,#64748b); margin-top: 6px; display: inline-flex; align-items: center; gap: 6px; }
.ew-flash-hint i { font-size: 13px; }
.ew-back-body { flex: 1; display: flex; flex-direction: column; justify-content: center; gap: 14px; text-align: left; }
.ew-back-word { font-size: calc(34px*var(--card-font-scale,1)); font-weight: 800; color: var(--primary,#0f766e); letter-spacing: .5px; line-height: 1.3; word-break: break-word; }
.ew-back-def { font-size: calc(16px*var(--card-font-scale,1)); line-height: 1.8; color: var(--ink,#1d1d1d); }
.ew-back-def.ew-def-en { background: transparent; border-left: 3px solid var(--primary, #0f766e); padding-left: 14px; }
.ew-back-hint { font-size: 12px; color: var(--ink-3,#64748b); cursor: pointer; padding: 6px; }
.ew-back-hint:hover { color: var(--primary,#0f766e); }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    function parseList(t) {
        if (t == null) return [];
        if (Array.isArray(t)) return t;
        if (typeof t !== 'string') return [String(t)];
        try {
            var arr = JSON.parse(t);
            if (Array.isArray(arr)) return arr;
        } catch (e) {}
        return [t];
    }
    function defBlock(items, extraClass) {
        if (!items.length) return '';
        var html = '<div class="' + (extraClass || '') + '" style="font-size:calc(16px*var(--card-font-scale,1));line-height:1.8">';
        items.forEach(function (t) { html += '<div>' + esc(t) + '</div>'; });
        html += '</div>';
        return html;
    }
    window.cardTemplate = {
        name: 'English Word (Simple)',
        fields: [
            { key: 'word', label: '单词', hideable: false },
            { key: 'phonetic_us', label: '音标' },
            { key: 'paraphrase_en', label: '英文释义' },
            { key: 'paraphrase_zh', label: '中文释义' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function h(k, html) { return isHidden(k) ? '' : html; }

            var markActive = data.is_unknown === 1 ? ' is-active' : '';
            var favActive = data.is_favorite === 1 ? ' is-active' : '';
            var isMarked = data.is_unknown === 1;

            /* ---- Normal card (unmarked): word + phonetic + both definitions ---- */
            if (!isMarked) {
                var html = '';
                html += '<div class="dc-card ew flex flex-col max-h-[560px] bg-[var(--card-bg)] text-[var(--ink)] border border-[var(--line)] rounded-2xl p-4 shadow-sm mb-4" data-card-id="' + data.id + '">';
                html += '<div class="flex items-start justify-between gap-3 mb-3 shrink-0">';
                html += '<div class="flex items-baseline gap-2 flex-wrap min-w-0">';
                html += '<span class="ew-index text-xs font-semibold">' + String(data.current_order).padStart(2, '0') + '</span>';
                html += h('word', '<span class="ew-word text-2xl font-bold" style="font-size:calc(24px*var(--card-font-scale,1))">' + esc(d.word) + '</span>');
                html += h('phonetic_us', '<span class="ew-phon text-sm" style="font-size:calc(13px*var(--card-font-scale,1))">/' + esc(d.phonetic_us) + '/</span>');
                html += '</div>';
                html += '<div class="flex items-center gap-2 shrink-0">';
                html += '<button class="dc-act act-play" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>';
                html += '<button class="dc-act act-mark' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>';
                html += '<button class="dc-act act-fav' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
                html += '</div></div>';
                html += '<div class="dc-scroll flex-1 min-h-0 overflow-y-auto space-y-3">';
                html += defBlock(parseList(d.paraphrase_zh), '');
                html += defBlock(parseList(d.paraphrase_en), 'ew-def-en');
                html += '</div></div>';
                return html;
            }

            /* ---- Flashcard (marked): front = word+phonetic, back = definitions ---- */
            var flipped = data._flashFlipped === true;
            var wordHtml = h('word', '<div class="ew-flash-word">' + esc(d.word) + '</div>');
            var phonHtml = h('phonetic_us', '<div class="ew-flash-phon">/' + esc(d.phonetic_us) + '/</div>');

            var frontDefs = '';
            if (!isHidden('paraphrase_zh') && parseList(d.paraphrase_zh).length) {
                frontDefs += '<div class="ew-back-def">' + parseList(d.paraphrase_zh).map(esc).join('<br>') + '</div>';
            }
            if (!isHidden('paraphrase_en') && parseList(d.paraphrase_en).length) {
                frontDefs += '<div class="ew-back-def ew-def-en">' + parseList(d.paraphrase_en).map(esc).join('<br>') + '</div>';
            }

            var html = '';
            html += '<div class="dc-card ew flash flex flex-col bg-[var(--card-bg)] text-[var(--ink)] border border-[var(--line)] rounded-2xl shadow-sm mb-4 highlighted" data-card-id="' + data.id + '">';
            html += '<div class="ew-flash' + (flipped ? ' flipped' : '') + '">';
            html += '<div class="ew-flash-inner">';
            /* Front face */
            html += '<div class="ew-face ew-front">';
            html += '<div class="ew-flash-head">';
            html += '<div class="ew-flash-badge"><i class="fa-solid fa-layer-group"></i> ' + (data.current_order ? String(data.current_order).padStart(2, '0') : '') + ' · 闪卡</div>';
            html += '<div class="ew-flash-actions">';
            html += '<button class="dc-act act-play" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>';
            html += '<button class="dc-act act-mark' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>';
            html += '<button class="dc-act act-fav' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
            html += '</div></div>';
            html += '<div class="ew-flash-body" data-action="flip">';
            html += wordHtml;
            html += phonHtml;

            html += '</div>';
            html += '</div>';
            /* Back face */
            html += '<div class="ew-face ew-back">';
            html += '<div class="ew-back-body" data-action="flip">';
            html += '<div class="ew-back-word">' + esc(d.word) + '</div>';
            html += frontDefs;

            html += '</div>';
            html += '</div>';
            html += '</div></div></div>';
            return html;
        },
        init: function (cardElement, cardData, api) {
            var pb = cardElement.querySelector('[data-action="play"]');
            if (pb) pb.addEventListener('click', function () {
                var d = (api.getCardData().data) || {};
                api.playAudio(d.word || '');
                api.track('audio_play');
            });
            var mb = cardElement.querySelector('[data-action="mark"]');
            if (mb) mb.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var fb = cardElement.querySelector('[data-action="favorite"]');
            if (fb) fb.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
            /* Flashcard flip: record definition_view when revealing the back,
               but NOT when flipping back to the front. */
            cardElement.querySelectorAll('[data-action="flip"]').forEach(function (el) {
                el.addEventListener('click', function () {
                    var d = api.getCardData();
                    var wasFlipped = d._flashFlipped === true;
                    d._flashFlipped = !wasFlipped;
                    if (!wasFlipped) api.track('definition_view');
                    api.rerender();
                });
            });
            cardElement.querySelectorAll('[data-action]').forEach(function (btn) {
                btn.addEventListener('mouseenter', function () {
                    var t = btn.dataset.tooltip; if (t && api.showTooltip) api.showTooltip(btn, t);
                });
                btn.addEventListener('mouseleave', function () { if (api.hideTooltip) api.hideTooltip(); });
            });
        }
    };
})();
